async def remove(ssid: str = None, name: str = None) -> Tuple[bool, str]:
    """ Remove a network. Depending on what is known, specify either ssid
    (in which case this function will call ``connection_exists`` to get the
    nmcli connection name) or the nmcli connection name directly.

    Returns (True, msg) if the connection was deleted, (False, msg) otherwise.
    """
    try:
        # TODO: use nmcli for this?
        with open("/etc/NetworkManager/system-connections", "r") as f:
            lines = f.readlines()
        for line in lines:
            if name is None:
                if ssid is not None and line.startswith(f"[{ssid}]"):
                    name = line.split("[")[1].split("]")[0]
                    break
            else:
                if line.startswith(f"[{name}]"):
                    break

        if name is None:
            raise Exception("No network with this SSID found")

        with open("/etc/NetworkManager/system-connections", "w") as f:
            for line in lines:
                if line.startswith(f"[{name}]"):
                    continue
                f.write(line)

        return (True, "Network deleted successfully")
    except Exception as e:
        return (False, f"Failed to delete network: {e}")

