def remove_all() -> Tuple[bool, str]:
    """ Remove all networks. """
    try:
        with open("/etc/NetworkManager/system-connections", "r") as f:
            lines = f.readlines()

        with open("/etc/NetworkManager/system-connections", "w") as f:
            for line in lines:
                if not line.startswith("["):
                    continue
                name = line.split("[")[1].split("]")[0]
                remove(name)

        return (True, "Networks deleted successfully")
    except Exception as e:
        return (False, f"Failed to delete networks: {e}")


